+        affected = true;
+        let events = group.events.get(eid);
+        if (!events) group.events.set(eid, (events = new Map()));
+        const previous = events.get(key);
+        // A pair that is added and removed (or vice versa) in one observation window cancels.
+        if ((previous === 'add' && eventType === 'remove') || (previous === 'remove' && eventType === 'add')) {
